/**
 * @name User input to regex pattern
 * @description Detecting if user input flows into regex patterns in soupsieve
 * @kind path-problem
 * @problem.severity error
 * @id py/soupsieve-regex-injection
 * @tags security
 *       external/cwe/cwe-1333
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs
import semmle.python.dataflow.new.RemoteFlowSources

module RegexInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Consider arguments to public API functions as sources
    exists(DataFlow::ParameterNode p |
      p.getParameter().getName() = "select" and // Common parameter name for selector?
      p.getScope().getEnclosingModule().getName() = "soupsieve"
    )
    or
    // More generic approach: arguments to functions in __init__.py
    exists(Function f, DataFlow::ParameterNode p |
      f.getScope().getEnclosingModule().getName() = "soupsieve" and
      f.getName() in ["compile", "select", "filter", "match", "closest"] and
      p.getParameter() = f.getArg(0) and
      source = p
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // Sink is the pattern argument of re.compile or re functions
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("re").getMember(["compile", "search", "match", "fullmatch", "split", "findall", "finditer", "sub", "subn"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module RegexInjectionFlow = TaintTracking::Global<RegexInjectionConfig>;
import RegexInjectionFlow::PathGraph

from RegexInjectionFlow::PathNode source, RegexInjectionFlow::PathNode sink
where RegexInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Regex pattern derived from user input $@.", source.getNode(), "user input"

/**
 * @name User input to regex compilation
 * @description Tracking flow from Soupsieve public API to regex compilation, which could lead to ReDoS.
 * @kind path-problem
 * @problem.severity error
 * @id py/soupsieve-redos-taint
 * @tags security
 *       external/cwe/cwe-1333
 *       external/cwe/cwe-400
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs
import semmle.python.Concepts

module ReDoSConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Public API of soupsieve
    exists(string funcName |
      funcName in ["compile", "select", "match", "filter", "closest", "iselect"] and
      source = API::moduleImport("soupsieve").getMember(funcName).getACall().getArg(0)
    )
    or
    // Also consider the 'compile' function inside css_parser if it's used internally
    source = API::moduleImport("soupsieve").getMember("css_parser").getMember("CSSParser").getACall().getArg(0)
  }

  predicate isSink(DataFlow::Node sink) {
    sink = API::moduleImport("re").getMember(["compile", "match", "search", "findall", "finditer", "split", "sub", "subn"]).getACall().getArg(0)
  }
}

module ReDoSFlow = TaintTracking::Global<ReDoSConfig>;
import ReDoSFlow::PathGraph

from ReDoSFlow::PathNode source, ReDoSFlow::PathNode sink
where ReDoSFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Regex compilation from $@.", source.getNode(), "user input"

/**
 * @name ReDoS via regex matching against user input
 * @description User-controlled CSS selectors used as the target string in regex operations can lead to ReDoS if the regex is vulnerable.
 * @kind path-problem
 * @problem.severity error
 * @id py/redos-css-matching
 * @tags security
 *       external/cwe/cwe-1333
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs
import semmle.python.Concepts

module ReDoSConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Parameters of public API functions
    exists(Function f |
      f.getName() in ["compile", "select", "filter", "match", "closest"] and
      f.getEnclosingModule().getName().matches("soupsieve%") and
      source.(DataFlow::ParameterNode).getParameter() = f.getArg(0)
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // re module functions: re.match(pattern, string)
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("re").getMember(["match", "search", "findall", "finditer", "split"]).getACall() and
      sink = call.getArg(1)
    )
    or
    // re module sub/subn: re.sub(pattern, repl, string)
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("re").getMember(["sub", "subn"]).getACall() and
      sink = call.getArg(2)
    )
    or
    // Compiled regex methods: pattern.match(string)
    // We approximate this by looking for calls to methods named match/search/etc on objects that might be regexes.
    // A more precise way is to track return values of re.compile, but that might be hard if they are global constants.
    // Let's try to be a bit generic: any call to match/search/findall/finditer/split where the object is NOT the re module itself.
    exists(DataFlow::CallCfgNode call, string methodName |
      methodName in ["match", "search", "findall", "finditer", "split", "sub", "subn"] and
      call.getFunction().(DataFlow::AttrRead).getAttributeName() = methodName and
      not call = API::moduleImport("re").getMember(methodName).getACall() and
      // For methods, the string is usually the first argument (arg 0)
      // except for sub/subn where it is arg 1 (repl is arg 0)? No, wait.
      // pattern.sub(repl, string, count=0)
      (
        (methodName in ["sub", "subn"] and sink = call.getArg(1)) or
        (not methodName in ["sub", "subn"] and sink = call.getArg(0))
      )
    )
  }
}

module ReDoSFlow = TaintTracking::Global<ReDoSConfig>;
import ReDoSFlow::PathGraph

from ReDoSFlow::PathNode source, ReDoSFlow::PathNode sink
where ReDoSFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential ReDoS: User input matches against regex at $@.", source.getNode(), "user input"

/**
 * @name Regex Injection
 * @description User input used in regex without escaping
 * @kind path-problem
 * @problem.severity error
 * @id py/regex-injection
 * @tags security
 *       external/cwe/cwe-1333
 *       external/cwe/cwe-730
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module RegexInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Parameters of public API functions
    exists(Function f |
      f.getName() in ["compile", "select", "filter", "match", "closest"] and
      f.getEnclosingModule().getName().matches("soupsieve%") and
      source.(DataFlow::ParameterNode).getParameter() = f.getArg(0)
    )
  }

  predicate isSink(DataFlow::Node sink) {
    sink = API::moduleImport("re").getMember(["compile", "match", "search", "findall", "finditer", "split", "sub", "subn"]).getACall().getArg(0)
  }

  predicate isBarrier(DataFlow::Node node) {
    // re.escape is a sanitizer
    node = API::moduleImport("re").getMember("escape").getACall()
  }
}

module RegexInjectionFlow = TaintTracking::Global<RegexInjectionConfig>;
import RegexInjectionFlow::PathGraph

from RegexInjectionFlow::PathNode source, RegexInjectionFlow::PathNode sink
where RegexInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Regex injection from $@.", source.getNode(), "user input"
